export function note(value) {}
export function construct(callback) {
  const ends = [];
  for (const given of [[Symbol.iterator], ["", 1.5, true], [undefined], [new Map([[1, 2]]), new Set([1])]]) {
    try {
      ends.push(typeof new callback(...given));
    } catch (error) {
      ends.push(
        error?.constructor?.name +
          ": " +
          String(error?.stack)
            .split("\n")
            .slice(1, 6)
            .map(line =>
              line
                .trim()
                .replace(/\(.*[\\/]/, "(")
                .replace(/^at [^ ]*[\\/]/, "at "),
            )
            .join(" < "),
      );
    }
  }
  return ends.join("\n");
}
